package com.everykill;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(EverykillConfig.GROUP)
public interface EverykillConfig extends Config
{
	String GROUP = "everykill";

	// ------------------------------------------------------------------
	@ConfigSection(
		name = "Panel & overlay",
		description = "What is drawn, and where",
		position = 10
	)
	String overlaySection = "overlaySection";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Session counter on the game canvas. Off by default - the side panel is the primary surface.",
		position = 11,
		section = overlaySection
	)
	default boolean showOverlay()
	{
		// spec-plugin-ux.md: "Off by default. When on, one compact box." an overlay
		// nobody asked for is clutter on someone else's screen.
		return false;
	}

	@ConfigItem(
		keyName = "compactOverlay",
		name = "Compact overlay",
		description = "One line instead of three.",
		position = 12,
		section = overlaySection
	)
	default boolean compactOverlay()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showGradeSplit",
		name = "Show grade split",
		description = "Uncontested / inferred / ambiguous breakdown. Off by default - it is a diagnostic, not a session stat.",
		position = 13,
		section = overlaySection
	)
	default boolean showGradeSplit()
	{
		// off by default, and NOT in the spec's overlay list. seeing "ambiguous 1"
		// appear mid-fight tells you someone is on your target - which is exactly the
		// in-fight signal the hard limits exist to keep out. useful for verifying
		// grading, so it stays available; just not on by default.
		return false;
	}

	// ------------------------------------------------------------------
	@ConfigSection(
		name = "Notices",
		description = "How much it interrupts you",
		position = 20
	)
	String noticeSection = "noticeSection";

	@ConfigItem(
		keyName = "noticeLevel",
		name = "Notice level",
		description = "Everything is noisy. Silent still records everything.",
		position = 21,
		section = noticeSection
	)
	default NoticeLevel noticeLevel()
	{
		return NoticeLevel.NOTABLE_ONLY;
	}

	@ConfigItem(
		keyName = "chatNotices",
		name = "Chat messages",
		description = "Posts notices to your chatbox as a client message.",
		position = 22,
		section = noticeSection
	)
	default boolean chatNotices()
	{
		return true;
	}

	@ConfigItem(
		keyName = "milestones",
		name = "KC milestones",
		description = "100 / 250 / 500 / 1k / 2.5k / 5k / 10k. Counted at uncontested grade only.",
		position = 23,
		section = noticeSection
	)
	default boolean milestones()
	{
		return true;
	}

	// ------------------------------------------------------------------
	@ConfigSection(
		name = "Recording",
		description = "What the plugin records",
		position = 0
	)
	String recordingSection = "recordingSection";

	@ConfigItem(
		keyName = "recordKills",
		name = "Record kills",
		description = "The plugin does nothing at all with this off.",
		position = 1,
		section = recordingSection
	)
	default boolean recordKills()
	{
		return true;
	}

	// ------------------------------------------------------------------
	@ConfigItem(
		keyName = "dinkNotifications",
		name = "Send milestones to Dink",
		description = "Sends kill-count milestones and fastest kills to Dink, which forwards them to your Discord webhook. Requires the Dink plugin with 'External Plugin Requests' enabled. Everykill never contacts Discord itself and never sees your webhook URL.",
		position = 24,
		section = noticeSection
	)
	default boolean dinkNotifications()
	{
		return false;
	}

	@ConfigSection(
		name = "Upload & privacy",
		description = "Nothing leaves your machine unless you turn this on",
		position = 30,
		closedByDefault = true
	)
	String uploadSection = "uploadSection";

	/**
	 * Off by default, behind RuneLite's own confirmation dialog.
	 *
	 * <p>That warning string is hub-mandated, word for word, for anything touching a
	 * third-party server. Do not reword it, do not tidy it, do not "improve" it.
	 *
	 * <p>Nothing reads this yet - upload is P3, after delete and export exist. It's
	 * here now purely so nobody can ship the feature and forget the disclosure.
	 */
	@ConfigItem(
		keyName = "uploadEnabled",
		name = "Upload to the site",
		description = "Sends your recorded kills so you are ranked. Each kill sends: monster id and name, combat level, region, kill grade, your damage and other players' damage, hit counts, fight length, and the items dropped. Your account name is NEVER sent - you are identified by a random id generated on this computer. Uploading ranks you pseudonymously; putting a name on a public leaderboard is a separate opt-in below. Kills recorded while this is off are never uploaded, including if you turn it on later - the toggle means from now on.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 31,
		section = uploadSection
	)
	default boolean uploadEnabled()
	{
		return false;
	}

	/**
	 * The one address kills are sent to. Not user-editable, by Hub rule.
	 *
	 * <p><i>"One hardcoded API domain. No user-supplied URLs, ever."</i> A config field
	 * that POSTs to any host a user types is the single most objectionable thing a
	 * plugin can ship — it turns an audited destination into an arbitrary one, and no
	 * reviewer can verify where a player's data ends up.
	 *
	 * <p>This was editable while nothing was deployed, which was a dev convenience
	 * wearing a config item's clothes. {@link #devUploadUrl()} replaces it and only
	 * accepts loopback.
	 */
	String UPLOAD_URL = "https://api.everykill.com";

	/**
	 * Points the plugin at a reference server on this machine. Loopback only.
	 *
	 * <p>Exists so the ingest server can be developed against without shipping an
	 * editable production URL. Anything that is not {@code 127.0.0.1} or
	 * {@code localhost} is ignored and {@link #UPLOAD_URL} is used instead, so this
	 * cannot be talked into sending someone's kills to a stranger's host.
	 */
	@ConfigItem(
		keyName = "devUploadUrl",
		name = "Local server (advanced)",
		description = "For testing against a local ingest server only, e.g. http://127.0.0.1:8790. Anything that is not on this computer is ignored. Leave blank.",
		position = 39,
		section = uploadSection
	)
	default String devUploadUrl()
	{
		return "";
	}

	/**
	 * The second consent, and the only path an account name takes to the server.
	 *
	 * <p>GDPR 7(2) wants a consent request distinguishable from other matters, and
	 * bundling "send my kills" with "publish my name" is the bundled consent that
	 * gets invalidated. They are also two genuinely different asks: plenty of people
	 * want dryness maths without their name on a board.
	 *
	 * <p>Nothing reads this yet. It is here so the config text matches the published
	 * policy before the feature exists, not after.
	 */
	@ConfigItem(
		keyName = "publishName",
		name = "Publish my name",
		description = "Shows your display name on public leaderboards, including kills you already uploaded. Off means you are still ranked, just not named. Requires uploading. Turning this off deletes the name from the site; your ranks stay as unnamed entries.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 33,
		section = uploadSection
	)
	default boolean publishName()
	{
		return false;
	}

	/**
	 * Whether the account MODE is published alongside the name.
	 *
	 * <p>Separate from the name for a real safety reason, not tidiness. A public
	 * board that says <i>"Hardcore Ironman, 4,000 gargoyles this week"</i> is a
	 * target list — it tells a PKer the account has one life, plays a known monster,
	 * and plays it often. Mode is genuinely useful for comparing like with like, and
	 * genuinely dangerous attached to a name, so it gets its own switch.
	 *
	 * <p>Defaults ON because most accounts are mains and the comparison is the point;
	 * a player who does not want it toggles it, and the description says plainly what
	 * it reveals. Nothing here fires unless {@code publishName} is also on.
	 */
	@ConfigItem(
		keyName = "publishAccountType",
		name = "Show my account type",
		description = "Shows Ironman, Hardcore, Group and so on next to your name on public leaderboards. Turn this off to appear as an unranked account - useful if you would rather not advertise a hardcore or ironman account publicly. Only applies when your name is published.",
		position = 34,
		section = uploadSection
	)
	default boolean publishAccountType()
	{
		return true;
	}

	enum NoticeLevel
	{
		EVERYTHING("Everything"),
		NOTABLE_ONLY("Notable only"),
		BIG_ONLY("Big only"),
		SILENT("Silent");

		private final String label;

		NoticeLevel(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}

		/**
		 * Smallest milestone allowed to say anything at this level. Everything below
		 * still gets recorded - shutting up isn't the same as not counting.
		 */
		public int milestoneFloor()
		{
			switch (this)
			{
				case EVERYTHING:
					return 0;
				case NOTABLE_ONLY:
					return 500;
				case BIG_ONLY:
					return 2500;
				default:
					return Integer.MAX_VALUE;
			}
		}
	}
}

